code='''from collections import Counter

def transform(grid):
    g = [list(row) for row in grid]
    h, w = len(g), len(g[0])
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]
    # Find the full divider of color 2.
    div = None
    for r, row in enumerate(g):
        if all(v == 2 for v in row):
            div = ("h", r)
            break
    if div is None:
        for c in range(w):
            if all(g[r][c] == 2 for r in range(h)):
                div = ("v", c)
                break
    if div is None:
        return g
    pts = [(r, c) for r in range(h) for c in range(w)
           if g[r][c] != bg and g[r][c] != 2]
    if not pts:
        return g
    r0 = min(r for r, c in pts); r1 = max(r for r, c in pts)
    c0 = min(c for r, c in pts); c1 = max(c for r, c in pts)
    crop = [row[c0:c1+1] for row in g[r0:r1+1]]
    # Move the pattern toward the divider, then draw an 8 line on its far side.
    if div[0] == "h":
        d = div[1]
        if r0 > d:
            nr0 = d + 1
            nr1 = nr0 + (r1-r0)
            marker = nr1 + 1
            if marker >= h: marker = nr1
        else:
            nr1 = d - 1
            nr0 = nr1 - (r1-r0)
            marker = nr0 - 1
            if marker < 0: marker = nr0
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                g[r][c] = bg
        for rr, row in enumerate(crop):
            for cc, v in enumerate(row):
                g[nr0+rr][c0+cc] = v
        g[marker] = [8] * w
    else:
        d = div[1]
        if c0 > d:
            nc0 = d + 1
            nc1 = nc0 + (c1-c0)
            marker = nc1 + 1
            if marker >= w: marker = nc1
        else:
            nc1 = d - 1
            nc0 = nc1 - (c1-c0)
            marker = nc0 - 1
            if marker < 0: marker = nc0
        for r in range(r0, r1+1):
            for c in range(c0, c1+1):
                g[r][c] = bg
        for rr, row in enumerate(crop):
            for cc, v in enumerate(row):
                g[r0+rr][nc0+cc] = v
        for r in range(h):
            g[r][marker] = 8
    return g
'''
